import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"LocalSend 局域网传输设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/localsend.md","filePath":"zh-CN/user-guide/settings/localsend.md","lastUpdated":1785993908000}'),r={name:"zh-CN/user-guide/settings/localsend.md"};function n(s,a,i,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="localsend-局域网传输设置" tabindex="-1">LocalSend 局域网传输设置 <a class="header-anchor" href="#localsend-局域网传输设置" aria-label="Permalink to &quot;LocalSend 局域网传输设置&quot;">​</a></h1><p>Lertaro 内置与官方 <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> 兼容的局域网跨设备传输协议，支持在同一局域网下的手机、电脑设备之间快速互相发送文件、文件夹与纯文本。设置页面路径为<strong>设置 → LocalSend</strong>。</p><h2 id="基础设置" tabindex="-1">基础设置 <a class="header-anchor" href="#基础设置" aria-label="Permalink to &quot;基础设置&quot;">​</a></h2><ul><li><strong>启用 LocalSend 局域网传输</strong> —— 开关控制是否开启 LocalSend 传输服务。开启后托盘菜单将提供“发送到其他设备...”项目，并可响应全局快捷键。</li><li><strong>设备名称</strong> —— 本机在局域网中被其他 LocalSend 客户端识别时显示的别名。默认根据机器名称自动生成。</li><li><strong>服务端口</strong> —— 监听局域网传输请求的 HTTP/HTTPS 端口（默认为 <code>53317</code>）。</li></ul><h2 id="安全与加密" tabindex="-1">安全与加密 <a class="header-anchor" href="#安全与加密" aria-label="Permalink to &quot;安全与加密&quot;">​</a></h2><ul><li><strong>加密传输 (HTTPS)</strong> —— 开启后将使用 HTTPS 加密连接传输数据（需要对方设备也支持加密传输）。</li><li><strong>接收 PIN 码</strong> —— 可设置接收传输请求时需验证的 PIN 码（留空则不启用验证）。</li></ul><h2 id="接收与存储" tabindex="-1">接收与存储 <a class="header-anchor" href="#接收与存储" aria-label="Permalink to &quot;接收与存储&quot;">​</a></h2><ul><li><strong>自动保存文件</strong> —— 开启后将自动接收并保存来自信任客户端的文件，无需每次手动确认。</li><li><strong>保存目录</strong> —— 接收到的文件默认存放目录。</li></ul><h2 id="呼打与发送方式" tabindex="-1">呼打与发送方式 <a class="header-anchor" href="#呼打与发送方式" aria-label="Permalink to &quot;呼打与发送方式&quot;">​</a></h2><ul><li><strong>热键唤起</strong> —— 默认使用 <strong><code>Ctrl+S</code></strong> 快捷键（可在<a href="./hotkeys-page.html">热键设置</a>中重新绑定）或点击系统托盘菜单中的“发送到其他设备...”。</li><li><strong>模式切换</strong> —— 发送窗口提供 [发送文件 / 文件夹] 与 [发送文本] 模式切换，支持实时从搜索结果中拖拽文件添加。</li></ul>',10)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
